+                    startTime: DatetimeUtils.firstDayOfLastMonth().toISOString(),
+                    endTime: DatetimeUtils.endOfDay(DatetimeUtils.lastDayOfLastMonth()).toISOString(),
+                }),
+            );
+        });
+    });
+});
diff --git a/src/dimensions/dto/dimensionTiers.gold.spec.ts b/src/dimensions/dto/dimensionTiers.gold.spec.ts
new file mode 100644
index 0000000000000000000000000000000000000000..9480f4a03c7b41a084f648214a574e2f3e1a1a9f
